    }

    html:not(.dlm-shopify-privacy-banner-visible) #shopify-pc__banner,
    html:not(.dlm-shopify-privacy-banner-visible) .shopify-pc__banner__wrapper,
    html:not(.dlm-shopify-privacy-banner-visible) .shopify-pc__prefs,
